INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (1, 'YaMe.vn', 422450.0, '2026-05-21 11:40:31', 'Quần Jeans Baggy Fit DurableTex™ The Original 053 1. Phom Loose Fit – Thoải mái nhưng vẫn cực kỳ tôn dáng Kỹ thuật Pence Gối: Các đường chiết ben vùng gối giúp quần có độ cong nhẹ, đứng phom tự nhiên, không bị đổ sụp hay "nuốt dáng" khi mặc. Cử động dễ dàng: Thiết kế thông minh tạo khoảng trống vừa đủ tại gối, giúp bạn đứng ngồi linh hoạt, không lo căng tức vải. Ôm gọn vùng hông: Thân sau được xử lý chiết ben đôi giúp quần ôm vừa vặn vùng mông, tránh tình trạng hở lưng khi cúi người. 2. Chất liệu DurableTex™ 11,8oz – Bền bỉ và đứng dáng Vải Denim 11,8oz: Độ dày lý tưởng tạo cảm giác đầm tay, chắc chắn nhưng vẫn thoáng mát cho nhu cầu sử dụng hằng ngày. Sợi lai bền vững: Kết hợp Cotton và Polyester tái chế giúp tăng độ bền, giữ màu lâu và bảo vệ môi trường. Chống biến dạng: Vải hạn chế nhăn nhàu và chống tình trạng bai nhão, giúp quần luôn đẹp như mới sau nhiều lần giặt. 3. Kết cấu "Siêu bền" – Yên tâm vận động mạnh May móc xích đôi: Đường may đáy và đùi có độ co giãn theo bước chân, loại bỏ hoàn toàn nỗi lo bục chỉ. Chốt chặn chịu lực: Các điểm nhạy cảm như túi và khóa quần được gia cố dày dặn, thoải mái đựng đồ nặng mà không lo rách vải. Lớp khung xương ẩn: Lưng quần được ép keo chuyên dụng, giữ cho cạp quần luôn phẳng phiu, không bị vặn xoắn hay mất phom. TỔNG KẾT Sự lựa chọn hoàn hảo cho những ai thích phong cách rộng rãi nhưng vẫn yêu cầu sự bền bỉ, chỉn chu và thoải mái trong từng cử động. THÔNG TIN NHANH Chất liệu: DurableTex™ Cotton Blend Ultra Twill 11,8oz (81% Cotton 19% Polyester - bao gồm sợi tái chế) Chi tiết sản phẩm: F5 - Baggy Fit (Dáng Rộng), Pence gối định hình. Lưu ý giặt ủi: Lộn trái khi giặt và phơi, tách riêng đồ đậm/nhạt, không dùng chất tẩy mạnh. Mô tả ngắn Quần Jeans Denim Loose Fit, thiết kế ống rộng phá cách với kỹ thuật pence gối 3D định hình phom dáng, chất vải DurableTex™ bền bỉ và đường may chịu lực cao.', 74550.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheOriginal053_d396961f-a447-49f5-a513-e04ee43ebec8.jpg?v=1778752200', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheOriginal053XanhJean871.jpg?v=1778566446', 'Cotton', 'Quần Jeans Baggy Ống Cong 3D Giải Phóng Đôi Chân DurableTex™ The Original 053 Màu Xanh Jean 87 Dáng Siêu Rộng F5', 422450.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 2);
