INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (7, 'YaMe.vn', 377150.0, '2026-05-21 11:40:31', 'Áo Thun Cổ Polo CloudTouch™ The No Style 249 1. Phom dáng Super Boxy: Trẻ trung & Che khuyết điểm Thiết kế hình hộp: Tạo độ mở ngang rộng giúp vai trông vững chãi hơn và khéo léo che đi vòng bụng. Đứng phom tuyệt đối: Kết cấu rập có tính toán độ co rút, đảm bảo áo giữ đúng tỉ lệ chuẩn, không bị vặn vẹo hay biến dạng sau nhiều lần giặt. 2. Chất vải CloudTouch™ 270gsm: Dày dặn & Thoáng khí Công nghệ Double Face: Kỹ thuật dệt 2 mặt giúp bề mặt vải phẳng mịn, hạn chế tối đa tình trạng quăn mép cổ hay lai áo thường gặp ở các dòng vải mỏng. Cotton Blend cao cấp: Sự kết hợp giữa 87% Cotton (thoáng mát) và 13% Poly (bền màu) giúp áo ít xù lông, giữ màu cực tốt và luôn tạo cảm giác mềm mại trên da. 3. Chi tiết gia công cao cấp: Bền bỉ từng đường kim Chống chảy xệ vai: Đường may vai được tích hợp dây đệm chuyên dụng, giữ cầu vai luôn thẳng đẹp ngay cả khi treo móc lâu ngày. Cổ áo sắc sảo: Cấu trúc lá cổ được ép keo lụa định hình, tạo diện mạo chỉn chu, sắc nét như đồ may đo, phù hợp từ văn phòng đến dạo phố. TỔNG KẾT The No Style 249 là sự đầu tư xứng đáng cho nam giới ưu tiên sự bền bỉ, giúp bạn luôn tự tin với phom dáng vuông vức, chỉn chu mà không tốn công ủi phẳng. THÔNG TIN NHANH Chất liệu: CloudTouch™ Cotton Blend Ultra Double Face 270gsm Chi tiết sản phẩm: F5 - Super Boxy (Dáng Hộp), dây gia cố vai chống chảy xệ, cổ áo ép keo định hình, họa tiết nhãn ép. Lưu ý giặt ủi: Giặt máy chế độ bình thường (dưới 40°C), lộn trái khi giặt/phơi, không sấy khô để bảo vệ sợi vải. Xuất xứ : Việt Nam Mô tả ngắn Áo Polo phom Super Boxy hiện đại. Vải CloudTouch™ dày dặn, đứng dáng, che khuyết điểm hiệu quả và bền bỉ sau nhiều lần giặt.', 19850.0, 'Boxy Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheNoStyle249_2_94ca4083-a2ec-4c74-a62b-0551047aab87.jpg?v=1778142933', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheNoStyle249Reu761.jpg?v=1777964239', 'Cotton', 'Áo Polo Boxy Hack Dáng Che Bụng CloudTouch™ Cổ Áo Bản Lớn Cá Tính The No Style 249 Rêu 76 Dáng Hộp F5', 377150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 1);
