INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (22, 'YaMe.vn', 337450.0, '2026-05-21 11:40:31', 'Áo Sơ Mi Thanh Lịch AirDry™ The Minimalist 017 1. Chất liệu AirDry™ Jacquard: Mặc nhẹ như không, tự tin vận động Mát lạnh cả ngày: Thay vì cảm giác bí bách, cấu trúc dệt với hàng ngàn "lỗ thở" li ti giúp áo luôn thoáng khí. Dù bạn phải di chuyển ngoài trời nắng nóng, mồ hôi cũng sẽ bay hơi cực nhanh, không gây bết dính. Tôn dáng nhờ sọc chìm: Những đường kẻ sọc tinh tế được dệt trực tiếp vào vải tạo hiệu ứng thị giác giúp bạn trông cao và thon gọn hơn mà vẫn giữ được sự lịch lãm. Không lo biến dạng ống tay: Với độ đàn hồi cao, vải sẽ tự "co" về trạng thái cũ sau mỗi cử động. Bạn sẽ không còn thấy phần khuỷu tay áo bị phồng hay nhăn nhúm mất thẩm mỹ. 2. Phom dáng Regular Fit: Chỉn chu từ vai xuống bụng Vai áo vuông vức: Thiết kế cầu vai hai lớp giúp áo đứng dáng ngay cả với người có khung vai gầy. Bạn có thể thoải mái vươn tay, lái xe mà không cảm thấy bị kích hay căng xé mặt vải. Gọn gàng vùng bụng: Phom áo được tinh chỉnh để vừa vặn, che khuyết điểm bụng tốt nhưng không quá rộng thùng thình. Đặc biệt, vùng nách áo được xử lý kỹ để khi hạ tay xuống, vải luôn phẳng phiu, không bị đùn vải thừa. 3. Hoàn thiện tỉ mỉ: Mặc êm ái, bền bỉ qua năm tháng Chắc chắn từng đường kim: Với mật độ chỉ dày đặc, chiếc áo chịu được áp lực giặt máy thường xuyên mà không lo bung chỉ hay sờn mép. Mặt trong sạch mịn: Mọi đường may sườn được cuốn kín vào trong. Bạn sẽ cảm thấy sự êm ái tuyệt đối, không còn những đường vắt sổ thô ráp gây ngứa hay kích ứng da. Cổ áo "chuẩn chỉnh" như mới: Nhờ công nghệ ép keo nhiệt hiện đại, cổ áo luôn giữ được độ đứng, phẳng phiu, không bị nổi bong bóng hay dợn sóng kể cả sau hàng chục lần giặt. TỔNG KẾT Người bạn đồng hành lý tưởng cho quý ông công sở: áo nhẹ tênh, cực kỳ thoáng mát và giữ được phom dáng chỉn chu từ sáng sớm đến tối muộn. THÔNG TIN NHANH Chất liệu: AirDry™ Polyester Ultra Jacquard 130gsm, 100% Polyester. Chi tiết: F3 - Regular Fit (Dáng Tiêu Chuẩn), túi áo trước ngực, lai nhỏ. Lưu ý giặt ủi: Lộn trái khi giặt, sử dụng túi giặt để bảo vệ sợi vải. Ủi mặt trái với nhiệt độ thấp (tối đa 110°C), ưu tiên bàn là hơi nước. Xuất xứ: Việt Nam', 59550.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheMinimalist017_2_ee3ad21b-82a2-4203-b660-cea3f05fd3e9.jpg?v=1779263619', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheMinimalist017.jpg?v=1778239588', 'Mixed', 'Áo Sơ Mi Tay Dài Công Sở AirDry™ Vải Sọc Siêu Nhẹ Thoáng The Minimalist 017 Màu Xám Nhạt Dáng Vừa Vặn F3', 337450.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 1);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (23, 'YaMe.vn', 337450.0, '2026-05-21 11:40:31', 'Áo Sơ Mi Thanh Lịch AirDry™ The Minimalist 017 1. Chất liệu AirDry™ Jacquard: Mặc nhẹ như không, tự tin vận động Mát lạnh cả ngày: Thay vì cảm giác bí bách, cấu trúc dệt với hàng ngàn "lỗ thở" li ti giúp áo luôn thoáng khí. Dù bạn phải di chuyển ngoài trời nắng nóng, mồ hôi cũng sẽ bay hơi cực nhanh, không gây bết dính. Tôn dáng nhờ sọc chìm: Những đường kẻ sọc tinh tế được dệt trực tiếp vào vải tạo hiệu ứng thị giác giúp bạn trông cao và thon gọn hơn mà vẫn giữ được sự lịch lãm. Không lo biến dạng ống tay: Với độ đàn hồi cao, vải sẽ tự "co" về trạng thái cũ sau mỗi cử động. Bạn sẽ không còn thấy phần khuỷu tay áo bị phồng hay nhăn nhúm mất thẩm mỹ. 2. Phom dáng Regular Fit: Chỉn chu từ vai xuống bụng Vai áo vuông vức: Thiết kế cầu vai hai lớp giúp áo đứng dáng ngay cả với người có khung vai gầy. Bạn có thể thoải mái vươn tay, lái xe mà không cảm thấy bị kích hay căng xé mặt vải. Gọn gàng vùng bụng: Phom áo được tinh chỉnh để vừa vặn, che khuyết điểm bụng tốt nhưng không quá rộng thùng thình. Đặc biệt, vùng nách áo được xử lý kỹ để khi hạ tay xuống, vải luôn phẳng phiu, không bị đùn vải thừa. 3. Hoàn thiện tỉ mỉ: Mặc êm ái, bền bỉ qua năm tháng Chắc chắn từng đường kim: Với mật độ chỉ dày đặc, chiếc áo chịu được áp lực giặt máy thường xuyên mà không lo bung chỉ hay sờn mép. Mặt trong sạch mịn: Mọi đường may sườn được cuốn kín vào trong. Bạn sẽ cảm thấy sự êm ái tuyệt đối, không còn những đường vắt sổ thô ráp gây ngứa hay kích ứng da. Cổ áo "chuẩn chỉnh" như mới: Nhờ công nghệ ép keo nhiệt hiện đại, cổ áo luôn giữ được độ đứng, phẳng phiu, không bị nổi bong bóng hay dợn sóng kể cả sau hàng chục lần giặt. TỔNG KẾT Người bạn đồng hành lý tưởng cho quý ông công sở: áo nhẹ tênh, cực kỳ thoáng mát và g