INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (24, 'YaMe.vn', 301600.0, '2026-05-21 11:40:31', 'ID sản phẩm: #Y2010 133 Dép Da Lộn Đế Trấu Mềm Mại, Đàn Hồi. Loại sản phẩm: Dép Đế Trấu Màu sắc: Nâu Đậm Chất liệu: Da Suede - Đế trấu - Mặt đế EVA Kỹ thuật: Mặt đế được ứng dụng kỹ thuật tạo vân chống trượt độc đáo, với các văn bản được thiết kế tỉ mỉ tăng cường độ bám trên mọi bề mặt. Điều này mang lại sự an toàn tuyệt đối, giúp bạn tự động chuyển đổi ngay trên các bề mặt trượt. Phong cách: Năng động thông thường Nhân dịp: Hàng ngày Bộ sưu tập: #Y2010', 75400.0, 'Regular', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010133.jpg?v=1777083556', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010133.png?v=1778817815', 'Mixed', 'Dép Đế Trấu Mules Da Suede Mềm #Y2010 133 Nâu Đậm', 301600.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 4);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (25, 'YaMe.vn', 397600.0, '2026-05-21 11:40:31', 'Túi Gym #Y2010 200 Chất liệu: 100% Polyester Ưu điểm: Cơ chế "biến hình" 360°: Khóa kéo mở rộng đáy giúp tăng ngay 13cm chiều cao và 40% diện tích chứa đồ khi cần thiết. Vật liệu trượt nước: Khả năng trượt nước và chống bám bụi tuyệt vời, giữ túi luôn mới và dễ dàng vệ sinh bằng khăn ẩm. Hệ thống chịu tải gia cường: Dây đai bản lớn may xuyên suốt từ đáy túi, giúp phân bổ trọng lượng đồng đều, giảm áp lực đau vai khi mang nặng. Ngăn chứa khoa học: Khoang chính siêu rộng kết hợp cùng các ngăn phụ "tiện tay" giúp phân loại đồ dùng cá nhân, điện thoại, chìa khóa cực kỳ ngăn nắp. Thông số kỹ thuật Kích thước tiêu chuẩn: Ngang 58 x Cao 31 x Rộng 23 cm Dung tích tiêu chuẩn: ~41 Lít (Gọn gàng, linh hoạt) Kích thước sau mở rộng: Ngang 58 x Cao 44 x Rộng 23 cm Dung tích sau mở rộng: ~59 Lít (Siêu lớn, chứa mọi đồ đạc phát sinh) Phù hợp cho Người thường xuyên đi công tác Tín đồ du lịch tự túc Người tập thể thao chuyên sâu cần mang nhiều phụ kiện Sinh viên/Học sinh ngoại tỉnh phù hợp cho những chuyến về quê ngắn ngày Lưu ý bảo quản Lau sạch bằng khăn ẩm Không dùng chất tẩy mạnh Phơi nơi thoáng mát (không sấy nhiệt cao) Tổng kết Giải pháp "3 trong 1" hoàn hảo thay thế túi Gym, túi công tác và hành lý du lịch. Thiết kế thực dụng, bền bỉ, sẵn sàng cho mọi hành trình từ 2 đến 7 ngày. Xuất xứ: Trung Quốc Mô tả ngắn Túi du lịch nới rộng 2 trong 1, phom hình chữ nhật linh hoạt. Chất liệu Polyester trượt nước, nới rộng 13cm tức thì, sức chứa cực tốt cho hành trình 2-7 ngày.', 99400.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010200a.jpg?v=1776766395', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010200Den1.jpg?v=1776500853', 'Mixed', 'Túi Đa Năng Gym & Du Lịch Đáy Mở Rộng Kháng Nước Nhẹ Lau Là Sạch #Y2010 200 Màu Đen', 397600.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 3);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (26, 'YaMe.vn', 397600.0, '2026-05-21 11:40:31', 'Túi Gym #Y2010 200 Chất liệu: 100% Polyester Ưu điểm: Cơ chế "biến hình" 360°: Khóa kéo mở rộng đáy giúp tăng ngay 13cm chiều cao và 40% diện tích chứa đồ khi cần thiết. Vật liệu trượt nước: Khả năng trượt nước và chống bám bụi tuyệt vời, giữ túi luôn mới và dễ dàng vệ sinh bằng khăn ẩm. Hệ thống chịu tải gia cường: Dây đai bản lớn may xuyên suốt từ đáy túi, giúp phân bổ trọng lượng đồng đều, giảm áp lực đau vai khi mang nặng. Ngăn chứa khoa học: Khoang chính siêu rộng kết hợp cùng các ngăn phụ "tiện tay" giúp phân loại đồ dùng cá nhân, điện thoại, chìa khóa cực kỳ ngăn nắp. Thông số kỹ thuật Kích thước tiêu chuẩn: Ngang 58 x Cao 31 x Rộng 23 cm Dung tích tiêu chuẩn: ~41 Lít (Gọn gàng, linh hoạt) Kích thước sau mở rộng: Ngang 58 x Cao 44 x Rộng 23 cm Dung tích sau mở rộng: ~59 Lít (Siêu lớn, chứa mọi đồ đạc phát sinh) Phù hợp cho Người thường xuyên đi công tác Tín đồ du lịch tự túc Người tập thể thao chuyên sâu cần mang nhiều phụ kiện Sinh viên/Học sinh ngoại tỉnh phù hợp cho những chuyến về quê ngắn ngày Lưu ý bảo quản Lau sạch bằng khăn ẩm Không dùng chất tẩy mạnh Phơi nơi thoáng mát (không sấy nhiệt cao) Tổng kết Giải pháp "3 trong 1" hoàn hảo thay thế túi Gym, túi công tác và hành lý du lịch. Thiết kế thực dụng, bền bỉ, sẵn sàng cho mọi hành trình từ 2 đến 7 ngày. Xuất xứ: Trung Quốc Mô tả ngắn Túi du lịch nới rộng 2 trong 1, phom hình chữ nhật linh hoạt. Chất liệu Polyester trượt nước, nới rộng 13cm tức thì, sức chứa cực tốt cho hành trình 2-7 ngày.', 99400.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010200a.jpg?v=1776766395', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010200BeNhat1.jpg?v=1776500656', 'Mixed', 'Túi Đa Năng Gym & Du Lịch Đáy Mở Rộng Kháng Nước Nhẹ Lau Là Sạch #Y2010 200 Màu Be Nhạt', 397600.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 3);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (27, 'YaMe.vn', 397600.0, '2026-05-21 11:40:31', 'Túi Gym #Y2010 200 Chất liệu: 100% Polyester Ưu điểm: Cơ chế "biến hình" 360°: Khóa kéo mở rộng đáy giúp tăng ngay 13cm chiều cao và 40% diện tích chứa đồ khi cần thiết. Vật liệu trượt nước: Khả năng trượt nước và chống bám bụi tuyệt vời, giữ túi luôn mới và dễ dàng vệ sinh bằng khăn ẩm. Hệ thống chịu tải gia cường: Dây đai bản lớn may xuyên suốt từ đáy túi, giúp phân bổ trọng lượng đồng đều, giảm áp lực đau vai khi mang nặng. Ngăn chứa khoa học: Khoang chính siêu rộng kết hợp cùng các ngăn phụ "tiện tay" giúp phân loại đồ dùng cá nhân, điện thoại, chìa khóa cực kỳ ngăn nắp. Thông số kỹ thuật Kích thước tiêu chuẩn: Ngang 58 x Cao 31 x Rộng 23 cm Dung tích tiêu chuẩn: ~41 Lít (Gọn gàng, linh hoạt) Kích thước sau mở rộng: Ngang 58 x Cao 44 x Rộng 23 cm Dung tích sau mở rộng: ~59 Lít (Siêu lớn, chứa mọi đồ đạc phát sinh) Phù hợp cho Người thường xuyên đi công tác Tín đồ du lịch tự túc Người tập thể thao chuyên sâu cần mang nhiều phụ kiện Sinh viên/Học sinh ngoại tỉnh phù hợp cho những chuyến về quê ngắn ngày Lưu ý bảo quản Lau sạch bằng khăn ẩm Không dùng chất tẩy mạnh Phơi nơi thoáng mát (không sấy nhiệt cao) Tổng kết Giải pháp "3 trong 1" hoàn hảo thay thế túi Gym, túi công tác và hành lý du lịch. Thiết kế thực dụng, bền bỉ, sẵn sàng cho mọi hành trình từ 2 đến 7 ngày. Xuất xứ: Trung Quốc Mô tả ngắn Túi du lịch nới rộng 2 trong 1, phom hình chữ nhật linh hoạt. Chất liệu Polyester trượt nước, nới rộng 13cm tức thì, sức chứa cực tốt cho hành trình 2-7 ngày.', 99400.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010200a.jpg?v=1776766395', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010200_bb121c43-aa5d-4dca-b3a5-48a252cdb7f8.jpg?v=1777970577', 'Mixed', 'Túi Đa Năng Gym & Du Lịch Đáy Mở Rộng Kháng Nước Nhẹ Lau Là Sạch #Y2010 200 Màu Xanh Lá Đậm', 397600.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 3);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (28, 'YaMe.vn', 282150.0, '2026-05-21 11:40:31', 'Túi Tote #Y2010 193 Chất liệu: 100% Cotton Ưu điểm: Chất liệu Canvas 100% Cotton: Sợi bông tự nhiên dệt mật độ cao tạo nên "bộ khung" dày dặn, chịu tải tốt cho laptop và giáo trình mà vẫn giữ được bề mặt mềm mại, bền bỉ theo năm tháng. Thiết kế linh hoạt 2-trong-1: Tùy biến giữa quai xách tay thanh lịch và dây đeo chéo có khóa điều chỉnh độ dài, giúp bạn rảnh tay khi di chuyển hoặc chạy xe máy. Cấu trúc đáy mở rộng: Phần đáy túi rộng giúp túi đứng vững trên mặt phẳng, tối ưu không gian chứa đồ và giúp việc sắp xếp vật dụng trở nên ngăn nắp hơn. Hệ thống ngăn phụ & Nút bấm an toàn: Ngăn phụ nhỏ bên trong giúp bảo vệ điện thoại, thẻ xe khỏi trầy xước. Miệng túi trang bị nút bấm kim loại chắc chắn, đảm bảo đồ đạc không bị rơi rớt. Thông số kỹ thuật Kích thước: Ngang 44cm x Cao 36cm x Rộng 14.5cm Dung tích: ~23L Phù hợp laptop: Dưới 15.5 inch Phù hợp cho Sinh viên Nhân viên văn phòng Người đi du lịch Mẹ bỉm sữa Người thường xuyên đi mua sắm Lưu ý bảo quản Giặt tay hoặc chế độ nhẹ Tránh thuốc tẩy mạnh Phơi nơi thoáng mát Tổng kết Canvas Tote #Y2010 193 là giải pháp lưu trữ bền bỉ với chất vải Cotton dày dặn và thiết kế đa năng, phù hợp cho mọi nhu cầu từ giảng đường đến văn phòng. Mô tả ngắn Túi Tote Canvas 100% Cotton phom rộng đa năng. Vải dày dặn, quai đeo 2 kiểu linh hoạt, đáy rộng và nhiều ngăn phụ tiện lợi.', 14850.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010193a.jpg?v=1776765843', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010193XanhLaDam1.jpg?v=1776494668', 'Cotton', 'Túi Tote Canvas Chịu Lực Ngăn Chứa Lớn "INSIDE OUT" #Y2010 193 Màu Xanh Lá Đậm', 282150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 3);
