INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (33, 'YaMe.vn', 317600.0, '2026-05-21 11:40:31', 'Túi Messenger #Y2010 191 Chất liệu: 100% Polyester Ưu điểm: Kháng nước vượt trội: Chất liệu Polyester dệt mật độ cao tạo hiệu ứng "lá sen", giúp nước mưa trượt đi tức thì, giữ đồ đạc luôn khô ráo. Ngăn chứa khoa học: Sức chứa lớn cho máy tính bảng, sổ tay nhưng vẫn giữ form dáng gọn gàng. Ngăn khóa sau lưng áp sát cơ thể giúp bảo vệ hộ chiếu và ví tiền an toàn tuyệt đối. Bảo mật kép: Sự kết hợp giữa khóa kéo kín và khóa bấm bản lớn tăng cường khả năng chống trộm và rơi rớt đồ khi vận động mạnh. Thiết kế công thái học: Khóa bấm xoay tự do chống xoắn dây đeo, kết hợp đai gài vali phía sau giúp giải phóng đôi vai, mang lại sự thong dong tối đa khi di chuyển tại sân bay, nhà ga. Thông số kỹ thuật Kích thước: Ngang 37 x Cao 25 x Rộng 8 (cm) Dung tích: 6.5L Phù hợp máy tính bảng: Dưới 12 inch Phù hợp cho Nhân sự văn phòng & Freelancer Người thường xuyên đi công tác Người yêu thích du lịch/dịch chuyển Học sinh sinh viên Lưu ý bảo quản Lau bằng khăn ướt khi có vết bẩn Giặt tay bằng xà phòng nhẹ Không dùng chất tẩy Phơi trong bóng râm Tránh máy sấy nhiệt cao Lưu ý quan trọng: Mặc dù bề mặt vải chống thấm tuyệt đối, nhưng để đảm bảo an toàn cho thiết bị nên tránh đi dưới mưa to kéo dài vì nước có thể thấm qua kẽ dây khóa. Tổng kết Giải pháp lưu trữ chuyên nghiệp, kháng nước bền bỉ và bảo mật thông minh, đồng hành tận tâm cùng bạn trên mọi cung đường công tác hay du lịch. Mô tả ngắn Túi Messenger phom chữ nhật tối giản, vải Polyester kháng nước. Khóa xoay linh hoạt, ngăn bảo mật sau lưng và đai gài vali cực tiện lợi.', 79400.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010191a.jpg?v=1776765271', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010191XanhLaDam1.jpg?v=1776484207', 'Mixed', 'Túi Messenger Kháng Nước Khóa Xoay Chống Xoắn Thông Minh #Y2010 191 Màu Xanh Lá Đậm', 317600.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 3);
