INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (38, 'YaMe.vn', 282150.0, '2026-05-21 11:40:31', 'Túi Cross #Y2010 181 Thông tin sản phẩm Chất liệu: Vải chính 100% Polyamide (Nylon) – Vải lót 100% Polyester. Ưu điểm: Thiết kế bán nguyệt "ôm sát": Đường cong thông minh giúp túi cố định vào cơ thể, triệt tiêu tình trạng rung lắc khi bạn đạp xe hay chạy bộ. Vật liệu Polyamide cao cấp: Bề mặt vải siêu bền, chống mài mòn và sở hữu hiệu ứng trượt nước nhẹ, bảo vệ đồ đạc an toàn trước những cơn mưa bất chợt. Tiện ích túi mini: Đi kèm một túi tròn nhỏ tháo rời, giúp bạn lấy nhanh tai nghe, chìa khóa hay tiền lẻ mà không cần mở ngăn chính. Quai đeo bản to: Phân tán lực đều lên vai, đi kèm khóa bấm nhựa chắc chắn, dễ dàng điều chỉnh độ dài theo vóc dáng. Thông số kỹ thuật Kích thước túi lớn: Ngang 45cm x Cao 26cm x Rộng 10cm, Dung tích ~7L Kích thước túi nhỏ: Đường kính 8cm x Rộng 2cm Phù hợp cho Người yêu thích sự năng động, hay di chuyển, đi làm hay đi chơi cần sự gọn gàng và tiện lợi. Lưu ý bảo quản Giặt tay trong nước lạnh và không sấy nhiệt để duy trì độ bền sợi vải. Do kết cấu khóa kéo có độ hở tự nhiên, vui lòng sử dụng thêm túi bảo vệ cho đồ điện tử nếu phải di chuyển lâu dưới mưa lớn. TỔNG KẾT Người bạn đồng hành lý tưởng cho nhịp sống năng động. Thiết kế ôm sát, chất liệu kháng nước và túi mini tiện lợi giúp bạn luôn gọn gàng, thoải mái khi đi làm hay dã ngoại. Mô tả ngắn Túi đeo bán nguyệt dáng ôm sát công thái học, chất vải Polyamide trượt nước bền bỉ, kèm túi mini rời tiện lợi cho người năng động.', 14850.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010181a.jpg?v=1776764702', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010181XanhLaDam1.jpg?v=1776414586', 'Mixed', 'Túi Đeo Chéo Cross Bag Trượt Nước Kèm Túi Mini Rời Tiện Ích  #Y2010 181 Màu Xanh Lá 