INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (40, 'YaMe.vn', 282150.0, '2026-05-21 11:40:31', 'Túi Sling #Y2010 185 Thông tin sản phẩm Chất liệu: Vải chính 100% Polyamide (Nylon), vải lót 100% Polyester. Ưu điểm: Cấu trúc hình kén: Ôm sát cơ thể, giúp triệt tiêu hiện tượng rung lắc và phân bổ trọng lượng đều, loại bỏ cảm giác đau mỏi vai khi đeo lâu. Chất liệu chuyên dụng: Vải Polyamide cao cấp (nguyên liệu đồ leo núi) siêu bền, chống trầy xước và kháng nước hiệu quả. Thao tác nhanh: Dây kéo thắt nút dễ cầm nắm và khóa bấm dây đeo chắc chắn giúp bạn lấy đồ hoặc tháo/mở túi chỉ trong vài giây. Sức chứa thông minh: Ngăn chính gọn gàng đựng vừa Tablet nhỏ, bình nước và các vật dụng cá nhân thiết yếu cho nhu cầu hằng ngày. Thông số kỹ thuật Kích thước: Ngang 17.5 x Cao 32 x Rộng 8 (cm) Phù hợp cho Người đi làm, đi học, đi trekking ngắn, đi dã ngoại/outdoor nhẹ và làm túi phụ tiện lợi khi đi du lịch. Lưu ý bảo quản Chỉ lau bằng khăn ẩm hoặc bàn chải mềm với xà phòng loãng. Tuyệt đối không giặt máy để giữ phom và lớp kháng nước. Xịt nano chống thấm định kỳ để duy trì khả năng trượt nước của bề mặt vải. Phơi khô tự nhiên tại nơi thoáng mát. Tránh ánh nắng gắt trực tiếp và nơi ẩm thấp để bảo vệ độ bền sợi vải. TỔNG KẾT Thiết kế hình kén giúp phân bổ trọng lực thông minh kết hợp cùng vải Polyamide chịu lực cao, mang lại trải nghiệm sử dụng nhẹ nhàng và bền bỉ theo thời gian.', 14850.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010185a.jpg?v=1776765051', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010185.jpg?v=1776764882', 'Mixed', 'Túi Đeo Sling Bag Kiểu Kén Tránh Mỏi Vải Siêu Bền Trượt Nước #Y2010 185 Màu Nâu', 282150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 3);
