INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (44, 'YaMe.vn', 397600.0, '2026-05-21 11:40:31', 'Túi Messenger #Y2010 238 Thông tin sản phẩm Chất liệu: Vải giả da Ưu điểm: Chất liệu vải giả da lộn: Bề mặt mài mịn, mang lại cảm giác êm ái, không gây thô ráp khi tiếp xúc với da và quần áo. Hệ thống khóa hai lớp: Sự kết hợp giữa khóa kéo miệng và nắp gập nam châm giúp bảo vệ tài sản tuyệt đối, loại bỏ nỗi lo mất đồ khi di chuyển nơi đông người. Sức chứa lớn & Tiện dụng: Ngăn chính rộng rãi đựng vừa laptop, sổ tay cùng ngăn nhỏ nội bộ giúp bạn sắp xếp chìa khóa, thẻ xe khoa học, dễ tìm. Thông số kỹ thuật Kích thước: Ngang 46.5 x Cao 31.5 x Rộng 15 (cm) Dung tích: ~21L Phù hợp cho laptop: Dưới 16 inch Đối tượng sử dụng Dân văn phòng và công sở, sinh viên và học sinh. Lưu ý bảo quản Lau bằng khăn ẩm Tránh đi mưa lớn Tránh ngâm lâu trong nước Không giặt máy để bảo vệ lớp da lộn TỔNG KẾT Một chiếc túi "hiểu chuyện" cho người bận rộn: vừa thời trang, vừa nhẹ vai lại an toàn tuyệt đối. Đồng hành cùng bạn từ văn phòng đến những buổi hẹn hò phố thị.', 99400.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010238a.jpg?v=1776766635', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010238_d44131ae-1b61-441b-abb7-73db5b43c901.jpg?v=1777970629', 'Mixed', 'Túi Messenger Vải Da Mềm Mượt Ngăn Rộng 2 Lớp Khóa #Y2010 238 Màu Nâu', 397600.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 3);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (45, 'YaMe.vn', 472150.0, '2026-05-21 11:40:31', 'Quần Jeans Regular Fit CloudTouch™ The Original 057 1. Chất liệu CloudTouch™ Êm ái Mềm mại: Sự kết hợp giữa Cotton và sợi Rayon (bột gỗ) giúp triệt tiêu sự thô ráp, mang lại bề mặt phẳng mịn, mát khi tiếp xúc với da. Co giãn linh hoạt: 2% sợi Spandex tạo độ đàn hồi nhẹ, loại bỏ cảm giác gò bó khi đứng lên ngồi xuống hay vận động cường độ cao. Định lượng 10oz: Độ dày vừa phải giúp quần đứng phom nhưng vẫn đảm bảo sự thoáng khí, không gây bí bách trong thời tiết nóng. 2. Phom dáng Regular Fit (F3): Cân bằng và tôn dáng Ống đứng suông thẳng: Thiết kế giúp chân trông thẳng và dài hơn, đồng thời che khuyết điểm bắp chân to hiệu quả. Cạp vừa: Giữ áo sơ vin cố định, tạo sự thoải mái cho vùng bụng và mang lại diện mạo chỉn chu. Hiệu ứng chùng dưới lai: Độ dài được tính toán để tạo nếp gấp nhẹ phía trên cổ giày, mang đến vẻ ngoài phóng khoáng mà không cần cắt sửa. 3. Kết cấu bền bỉ: Chống "bùng gối" và dão vải Hệ khung Polyester: 21% sợi Polyester đóng vai trò "bộ khung" giữ vải luôn co về trạng thái ban đầu, hạn chế tối đa tình trạng lồi đầu gối sau khi giặt. Chỉ may chịu lực cao: Sử dụng loại chỉ to và dai hơn thông thường, mọi điểm chịu lực trên quần đều được bảo vệ. Khuy mắt phụng: Chi tiết khuy được thêu bọc kỹ lưỡng, đảm bảo độ bền và tính thẩm mỹ cao nhất cho phần lưng quần. TỔNG KẾT The Original 057 là giải pháp Jeans hoàn hảo cho 12 giờ vận động: đủ lịch sự để họp hành, đủ mềm mịn để lái xe và di chuyển thoải mái cả ngày dài. THÔNG TIN NHANH Chất liệu: CloudTouch™ Rayon Blend Plus Twill 10oz (68% Cotton, 21% Polyester, 9% Rayon, 2% Spandex) Chi tiết: F3 - Regular Fit (Dáng Tiêu Chuẩn), ống đứng, cạp vừa. Lưu ý giặt ủi: Lộn trái khi giặt, tránh thuốc tẩy mạnh, không phơi trực tiếp dưới nắng gắt để bảo vệ sợi co giãn.', 24850.0, 'Regular', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheOriginal057_2.jpg?v=1777345625', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheOriginal057XanhDuongDam1.jpg?v=1775645606', 'Cotton', 'Quần Jeans CloudTouch™ Mặt Vải Êm Ái Giữ Phom Đứng Dáng The Original 057 Màu Xanh Dương Đậm Dáng Vừa Vặn F3', 472150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 2);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (46, 'YaMe.vn', 472150.0, '2026-05-21 11:40:31', 'Quần Jeans Regular Fit CloudTouch™ The Original 057 1. Chất liệu CloudTouch™ Êm ái Mềm mại: Sự kết hợp giữa Cotton và sợi Rayon (bột gỗ) giúp triệt tiêu sự thô ráp, mang lại bề mặt phẳng mịn, mát khi tiếp xúc với da. Co giãn linh hoạt: 2% sợi Spandex tạo độ đàn hồi nhẹ, loại bỏ cảm giác gò bó khi đứng lên ngồi xuống hay vận động cường độ cao. Định lượng 10oz: Độ dày vừa phải giúp quần đứng phom nhưng vẫn đảm bảo sự thoáng khí, không gây bí bách trong thời tiết nóng. 2. Phom dáng Regular Fit (F3): Cân bằng và tôn dáng Ống đứng suông thẳng: Thiết kế giúp chân trông thẳng và dài hơn, đồng thời che khuyết điểm bắp chân to hiệu quả. Cạp vừa: Giữ áo sơ vin cố định, tạo sự thoải mái cho vùng bụng và mang lại diện mạo chỉn chu. Hiệu ứng chùng dưới lai: Độ dài được tính toán để tạo nếp gấp nhẹ phía trên cổ giày, mang đến vẻ ngoài phóng khoáng mà không cần cắt sửa. 3. Kết cấu bền bỉ: Chống "bùng gối" và dão vải Hệ khung Polyester: 21% sợi Polyester đóng vai trò "bộ khung" giữ vải luôn co về trạng thái ban đầu, hạn chế tối đa tình trạng lồi đầu gối sau khi giặt. Chỉ may chịu lực cao: Sử dụng loại chỉ to và dai hơn thông thường, mọi điểm chịu lực trên quần đều được bảo vệ. Khuy mắt phụng: Chi tiết khuy được thêu bọc kỹ lưỡng, đảm bảo độ bền và tính thẩm mỹ cao nhất cho phần lưng quần. TỔNG KẾT The Original 057 là giải pháp Jeans hoàn hảo cho 12 giờ vận động: đủ lịch sự để họp hành, đủ mềm mịn để lái xe và di chuyển thoải mái cả ngày dài. THÔNG TIN NHANH Chất liệu: CloudTouch™ Rayon Blend Plus Twill 10oz (68% Cotton, 21% Polyester, 9% Rayon, 2% Spandex) Chi tiết: F3 - Regular Fit (Dáng Tiêu Chuẩn), ống đứng, cạp vừa. Lưu ý giặt ủi: Lộn trái khi giặt, tránh thuốc tẩy mạnh, không phơi trực tiếp dưới nắng gắt để bảo vệ sợi co giãn.', 24850.0, 'Regular', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheOriginal057_2.jpg?v=1777345625', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheOriginal057_e232baea-7b20-4c57-bfcd-0eb56585fdfe.jpg?v=1777345625', 'Cotton', 'Quần Jeans CloudTouch™ Mặt Vải Êm Ái Giữ Phom Đứng Dáng The Original 057 Màu Xanh Dương Dáng Vừa Vặn F3', 472150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 2);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (47, 'YaMe.vn', 472150.0, '2026-05-21 11:40:31', 'Quần Jeans Regular Fit FlexFit™ The Original 056 1. Chất vải FlexFit™: Êm ái và linh hoạt Mềm mịn: Sợi Rayon giúp bề mặt vải mượt hơn, không còn cảm giác thô ráp gây ngứa hay khó chịu cho da. Co giãn tốt: Loại bỏ cảm giác căng tức ở đùi và mông khi ngồi hay di chuyển nhờ độ đàn hồi lý tưởng. Bền bỉ: Pha trộn sợi Polyester giúp quần giữ màu lâu, ít nhăn nhàu và giữ bề mặt phẳng phiu sau khi giặt. 2. Phom dáng F3 Regular: Tôn dáng, che khuyết điểm Ống đứng: Thiết kế suông thẳng từ gối xuống gấu giúp đôi chân trông thẳng và dài hơn. Tôn vòng ba: Đường cắt phía sau giúp ôm nhẹ và tạo sự săn chắc, gọn gàng cho vóc dáng. Lai quần trẻ trung: Độ dài được tính toán để tạo nếp gấp nhẹ khi mang giày, cho phong cách phóng khoáng. 3. Gia công cao cấp & Bền bỉ Lưng quần chắc chắn: Hai đường chỉ may song song giúp thắt lưng không bị giãn hay mất phom sau thời gian dài. Khuy mắt phụng: Kỹ thuật đóng khuy cao cấp giúp lỗ khuy không bị tưa chỉ, thao tác cài mở mượt mà. Chỉ may dày: Tăng cường khả năng chịu lực tại các đường nối, thoải mái vận động mạnh không lo bục chỉ. TỔNG KẾT Giải pháp Jeans hiện đại cho nam giới: đứng phom chắc chắn nhưng vẫn đảm bảo sự linh hoạt, dễ chịu tuyệt đối trong mọi cử động hằng ngày. THÔNG TIN NHANH Chất liệu: FlexFit™ Rayon Blend Plus Twill 10,2oz (69% Cotton 20% Polyester 9% Rayon 2% Spandex) Chi tiết sản phẩm: F3 - Regular Fit (Dáng Tiêu Chuẩn), cạp vừa, ống đứng, khuy mắt phụng cao cấp. Lưu ý giặt ủi: Lộn trái khi giặt máy chế độ nhẹ, không sấy nhiệt cao để bảo vệ sợi co giãn Spandex.', 24850.0, 'Slim Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheOriginal056_2_c233a87d-3c64-4911-b9f4-d1994ab3415d.jpg?v=1777346860', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheOriginal056_7015bca6-7035-4a14-bd64-da3ce68c503f.jpg?v=1777346860', 'Cotton', 'Quần Jeans FlexFit™ Mềm Mại Giữ Dáng Chuẩn Hạn Chế Nếp Nhăn The Original 056 Màu Xanh Dương Nhạt Dáng Vừa Vặn F3', 472150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 2);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (48, 'YaMe.vn', 472150.0, '2026-05-21 11:40:31', 'Quần Jeans Regular Fit FlexFit™ The Original 056 1. Chất vải FlexFit™: Êm ái và linh hoạt Mềm mịn: Sợi Rayon giúp bề mặt vải mượt hơn, không còn cảm giác thô ráp gây ngứa hay khó chịu cho da. Co giãn tốt: Loại bỏ cảm giác căng tức ở đùi và mông khi ngồi hay di chuyển nhờ độ đàn hồi lý tưởng. Bền bỉ: Pha trộn sợi Polyester giúp quần giữ màu lâu, ít nhăn nhàu và giữ bề mặt phẳng phiu sau khi giặt. 2. Phom dáng F3 Regular: Tôn dáng, che khuyết điểm Ống đứng: Thiết kế suông thẳng từ gối xuống gấu giúp đôi chân trông thẳng và dài hơn. Tôn vòng ba: Đường cắt phía sau giúp ôm nhẹ và tạo sự săn chắc, gọn gàng cho vóc dáng. Lai quần trẻ trung: Độ dài được tính toán để tạo nếp gấp nhẹ khi mang giày, cho phong cách phóng khoáng. 3. Gia công cao cấp & Bền bỉ Lưng quần chắc chắn: Hai đường chỉ may song song giúp thắt lưng không bị giãn hay mất phom sau thời gian dài. Khuy mắt phụng: Kỹ thuật đóng khuy cao cấp giúp lỗ khuy không bị tưa chỉ, thao tác cài mở mượt mà. Chỉ may dày: Tăng cường khả năng chịu lực tại các đường nối, thoải mái vận động mạnh không lo bục chỉ. TỔNG KẾT Giải pháp Jeans hiện đại cho nam giới: đứng phom chắc chắn nhưng vẫn đảm bảo sự linh hoạt, dễ chịu tuyệt đối trong mọi cử động hằng ngày. THÔNG TIN NHANH Chất liệu: FlexFit™ Rayon Blend Plus Twill 10,2oz (69% Cotton 20% Polyester 9% Rayon 2% Spandex) Chi tiết sản phẩm: F3 - Regular Fit (Dáng Tiêu Chuẩn), cạp vừa, ống đứng, khuy mắt phụng cao cấp. Lưu ý giặt ủi: Lộn trái khi giặt máy chế độ nhẹ, không sấy nhiệt cao để bảo vệ sợi co giãn Spandex.', 24850.0, 'Slim Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheOriginal056_2_c233a87d-3c64-4911-b9f4-d1994ab3415d.jpg?v=1777346860', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheOriginal056XanhDuong1.jpg?v=1775621539', 'Cotton', 'Quần Jeans FlexFit™ Mềm Mại Giữ Dáng Chuẩn Hạn Chế Nếp Nhăn The Original 056 Màu Xanh Dương Dáng Vừa Vặn F3', 472150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 2);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (49, 'YaMe.vn', 282150.0, '2026-05-21 11:40:31', 'Áo Thun Cổ Tròn FlexFit™ The No Style 241 1. Chất liệu FlexFit™ Extreme – Co giãn như lò xo Vải gân Rib 1x1 độc quyền: Định lượng 255gsm dày dặn, đầm tay. Độ đàn hồi 90%: Kết hợp 6% Spandex giúp phục hồi form tức thì. Vận động tự do: Thoải mái co giãn, không lo vải bị biến dạng hay nhão. 2. Công nghệ Sọc dệt Yarn-dyed – Bền màu theo tuổi thọ áo Sợi màu trực tiếp: Họa tiết sọc được dệt từ sợi đã nhuộm, không phải in. Độ bền tuyệt đối: Không bong tróc, không nứt vỡ đường sọc khi kéo giãn. Màu sắc sắc nét: Giữ độ tươi mới và đều màu sau nhiều lần giặt. 3. Form dáng Loose Fit – Phóng khoáng & Giấu khuyết điểm Khối Boxy thời thượng: Vai trễ và hạ nách sâu hiện đại. Khoảng không gian thở: Tạo độ thông thoáng giữa vải và da, không dính rít. Phong cách Unisex: Thiết kế phóng khoáng, tôn dáng cho cả nam và nữ. 4. Kỹ thuật may chuẩn cao cấp Vai áo: Gia cố dây chống giãn giúp giữ cầu vai phẳng, không chảy xệ. Lai & Tay áo: Bản may 3cm tạo độ nặng, giữ áo luôn rũ thẳng vuông vức. Cổ áo: Xử lý lấy dấu 4 điểm chốt giúp vòng cổ tròn đều, chống vặn xoắn. TỔNG KẾT Chiếc áo sọc "quốc dân" cân bằng hoàn hảo giữa độ dày đứng form và sự co giãn linh hoạt, mang lại vẻ ngoài chỉn chu, bền bỉ cho tủ đồ tối giản. THÔNG TIN NHANH Chất liệu: 94% Cotton, 6% Spandex (Định lượng 255gsm). Chi tiết: F4 - Loose Fit (Dáng Rộng), vai trễ, sọc dệt Yarn-dyed, gia cố vai chống giãn. Lưu ý giặt ủi: Giặt nước lạnh, lộn trái khi giặt/phơi. Không sấy nóng hoặc vặn xoắn mạnh để bảo vệ sợi co giãn.', 14850.0, 'Boxy Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheNoStyle241_3.jpg?v=1777364967', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheNoStyle241_4b7e9aed-0788-42f0-a5ac-1ddfd733831d.jpg?v=1777364963', 'Cotton', 'Áo Thun Sọc Phom Boxy Hack Dáng FlexFit™ Vải Co Giãn Thoáng Mát The No Style 241 Màu Trắng Đen Dáng Rộng Rãi F4', 282150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 1);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (50, 'YaMe.vn', 282150.0, '2026-05-21 11:40:31', 'Áo Thun Cổ Tròn FlexFit™ The No Style 241 1. Chất liệu FlexFit™ Extreme – Co giãn như lò xo Vải gân Rib 1x1 độc quyền: Định lượng 255gsm dày dặn, đầm tay. Độ đàn hồi 90%: Kết hợp 6% Spandex giúp phục hồi form tức thì. Vận động tự do: Thoải mái co giãn, không lo vải bị biến dạng hay nhão. 2. Công nghệ Sọc dệt Yarn-dyed – Bền màu theo tuổi thọ áo Sợi màu trực tiếp: Họa tiết sọc được dệt từ sợi đã nhuộm, không phải in. Độ bền tuyệt đối: Không bong tróc, không nứt vỡ đường sọc khi kéo giãn. Màu sắc sắc nét: Giữ độ tươi mới và đều màu sau nhiều lần giặt. 3. Form dáng Loose Fit – Phóng khoáng & Giấu khuyết điểm Khối Boxy thời thượng: Vai trễ và hạ nách sâu hiện đại. Khoảng không gian thở: Tạo độ thông thoáng giữa vải và da, không dính rít. Phong cách Unisex: Thiết kế phóng khoáng, tôn dáng cho cả nam và nữ. 4. Kỹ thuật may chuẩn cao cấp Vai áo: Gia cố dây chống giãn giúp giữ cầu vai phẳng, không chảy xệ. Lai & Tay áo: Bản may 3cm tạo độ nặng, giữ áo luôn rũ thẳng vuông vức. Cổ áo: Xử lý lấy dấu 4 điểm chốt giúp vòng cổ tròn đều, chống vặn xoắn. TỔNG KẾT Chiếc áo sọc "quốc dân" cân bằng hoàn hảo giữa độ dày đứng form và sự co giãn linh hoạt, mang lại vẻ ngoài chỉn chu, bền bỉ cho tủ đồ tối giản. THÔNG TIN NHANH Chất liệu: 94% Cotton, 6% Spandex (Định lượng 255gsm). Chi tiết: F4 - Loose Fit (Dáng Rộng), vai trễ, sọc dệt Yarn-dyed, gia cố vai chống giãn. Lưu ý giặt ủi: Giặt nước lạnh, lộn trái khi giặt/phơi. Không sấy nóng hoặc vặn xoắn mạnh để bảo vệ sợi co giãn.', 14850.0, 'Boxy Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheNoStyle241_5.jpg?v=1777364967', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheNoStyle241_2.jpg?v=1777365041', 'Cotton', 'Áo Thun Sọc Phom Boxy Hack Dáng FlexFit™ Vải Co Giãn Thoáng Mát The No Style 241 Màu Đen Trắng Dáng Rộng Rãi F4', 282150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 1);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (51, 'YaMe.vn', 472150.0, '2026-05-21 11:40:31', 'Quần Jeans Regular Fit CloudTouch™ The Original 058 1. Chất liệu CloudTouch™ - Bước tiến của Denim hiện đại Công thức 4 loại sợi: Kết hợp Cotton, Polyester, Rayon và Spandex tạo nên bề mặt vải Mềm - Mịn - Mát vượt trội so với Jeans truyền thống. Xử lý Fine Twill: Kiểu dệt vân chéo siêu nhỏ giúp bề mặt phẳng mịn, loại bỏ hoàn toàn cảm giác thô ráp hay ngứa ngáy khi ma sát với da. Định lượng 10oz: Độ dày tiêu chuẩn để quần đứng phom nhưng vẫn nhẹ nhàng, thoáng khí, phù hợp cho mọi hoạt động hàng ngày. 2. Phom dáng Regular Fit tôn dáng Ống đứng (Straight Leg): Thiết kế suông thẳng giúp che khuyết điểm chân, tạo hiệu ứng đôi chân thẳng và cân đối. Đáy vừa (Mid Rise): Vị trí cạp quần nằm tại hông, mang lại sự kín đáo và thoải mái, không gây tức bụng khi ngồi làm việc lâu. Độ chùng lai (Stacking): Chiều dài quần được tính toán để tạo độ nhăn tự nhiên trên giày, mang lại vẻ ngoài phóng khoáng, nam tính. 3. Kết cấu Heavy Duty - Bền bỉ theo thời gian Kỹ thuật móc xích kép: Đường may đáy và dọc sườn được gia cố chắc chắn, chịu lực căng cực tốt, ngăn chặn tình trạng bục chỉ khi vận động mạnh. Lưng quần ép Mex: Sử dụng lớp lót chuyên dụng giúp lưng quần luôn phẳng, không bị vặn xoắn hay dão sau nhiều lần giặt máy. TỔNG KẾT The Original 058 là sự kết hợp giữa diện mạo Denim cổ điển và cảm giác mặc êm ái của quần vải. Lựa chọn tối ưu cho nam giới cần sự chỉn chu văn phòng nhưng vẫn thoải mái vận động cả ngày. THÔNG TIN NHANH Chất liệu: CloudTouch™ Rayon Blend Plus Twill 10oz, 68% Cotton 21% Polyester 9% Rayon 2% Spandex Chi tiết sản phẩm: F3 - Regular Fit (Dáng Tiêu Chuẩn) Lưu ý giặt ủi: Lộn trái khi giặt và phơi, tránh ánh nắng gắt, giặt nước lạnh (&lt; 40°C) để bảo vệ sợi co giãn.', 24850.0, 'Regular', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheOriginal058_2.jpg?v=1777345884', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheOriginal058_4dd9d11b-7b4d-44bd-b393-a2ad88256764.jpg?v=1777345884', 'Cotton', 'Quần Jeans CloudTouch™ Mịn Mượt Chiều Da Che Khuyết Điểm Chân The Original 058 Màu Xanh Dương Đậm Dáng Vừa Vặn F3', 472150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 2);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (52, 'YaMe.vn', 117600.0, '2026-05-21 11:40:31', 'ID sản phẩm: NB 012 Nón Lưỡi Trai thể thao dù mỏng nhẹ, thiết kế đục lỗ thoát khí, giải quyết được vấn đề hầm nóng bí bách khi luyện tập thể thao. Loại sản phẩm: Nón phong cách Màu sắc: Xám Nhạt Chất liệu: Dù Thành phần: Polyester 100% Kỹ thuật: Đục lỗ 2 bên thân nón Phong Cách: Năng động và tối giản Bộ sưu tập: Non Branded', 29400.0, 'Regular', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/23822Thumb1.jpg?v=1775533281', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/23822Thumb5.jpg?v=1775533281', 'Mixed', 'Nón Dad Hat Dù Lỗ Lazer Thoáng Khí NB 012 Xám Nhạt', 117600.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 3);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (53, 'YaMe.vn', 757150.0, '2026-05-21 11:40:31', 'Áo Khoác Trucker ColorLock™ Tek Black Jean 003 1. Công nghệ vải ColorLock™ - Đen sâu bền bỉ Khóa màu từ lõi: Ứng dụng công nghệ nhuộm xơ Dope Dye, giúp sắc đen bám chặt từ trong sợi vải, không còn nỗi lo bạc màu hay trắng sờn ở các đường gân sau nhiều lần giặt. Mềm mịn vượt trội: Sự kết hợp giữa sợi Modal và Spandex tạo bề mặt êm ái, loại bỏ hoàn toàn sự thô cứng của Denim truyền thống. 2. Form dáng Boxy Cropped - Tôn dáng & Linh hoạt Hiệu ứng kéo dài chân: Thiết kế dáng ngắn (Cropped) giúp tỉ lệ cơ thể trông cao ráo và năng động hơn. Mặc lớp (Layering) thoải mái: Phần nách hạ sâu và thân vuông giúp bạn dễ dàng kết hợp cùng áo thun dày hoặc Hoodie mà không gây cộm hay gò bó. Tùy chỉnh linh hoạt: Hai nấc cài bên sườn hỗ trợ thu gọn vạt áo theo sở thích cá nhân. 3. Độ bền công nghiệp - Tỉ mỉ từng đường kim Đường may móc xích: Tăng độ co giãn tự nhiên cho các mối nối ở sườn và nách, giúp bạn thoải mái vận động mạnh mà không lo bục chỉ. Bền bỉ từng chi tiết: Miệng túi và nẹp áo được gia cố thêm đường may, đảm bảo áo luôn bền đẹp, không hỏng form dù giặt máy hay sử dụng thường xuyên. TỔNG KẾT Tek Black Jean 003 là sự giao thoa hoàn hảo giữa kỹ thuật khóa màu và form dáng hiện đại, mang lại trải nghiệm mặc Denim mềm mại, bền bỉ và cực kỳ tôn dáng. THÔNG TIN NHANH Chất liệu: ColorLock™ Modal Blend Ultra Twill, 49% Modal 49% Polyester 2% Spandex Chi tiết: F3 - Regular Fit (Dáng Tiêu Chuẩn), đường may móc xích, khóa bọ gia cố, nấc cài cá lai điều chỉnh. Lưu ý giặt ủi Lộn trái khi giặt máy ở chế độ nhẹ, tránh chất tẩy mạnh và không sấy ở nhiệt độ cao để bảo vệ sợi vải sinh học.', 39850.0, 'Boxy Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TekBlackJean003_57cae232-e14b-4377-a608-92c29a08ec3b.jpg?v=1774608639', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/AoKhoacTruckerColorLock_TekBlackJean003.jpg?v=1778223744', 'Denim', 'Áo Khoác Jean ColorLock™ Khóa Màu Đen Siêu Bền Tek Black Jean 003 Màu Đen Dáng Vừa Vặn F3', 757150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 1);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (54, 'YaMe.vn', 422450.0, '2026-05-21 11:40:31', 'Quần Kaki DurableTex™ The No Style 242 1. Form dáng Loose Fit: Rộng rãi và "Hack" chiều cao Thiết kế hạ đáy sâu: Triệt tiêu hoàn toàn cảm giác "kích đáy", cho phép vận động, đứng ngồi tự do không gây cấn bí. Hệ thống ly xếp 3D: Tạo khoảng trống thông minh tại hông đùi, giúp quần luôn đứng form thẳng tắp, không bám dính vào chân. Thông số Wide Leg tối ưu: Tăng gối chiều dài giúp tạo độ rũ trùm nhẹ lên giày, giúp đôi chân trông dài hơn mà vẫn gọn gàng. 2. Vải DurableTex™ 290gsm: Đanh chắc và Ít nhăn Dệt vân rổ (Basket Weave): Bề mặt hạt nổi li ti giúp giảm diện tích tiếp xúc với da, tạo sự khô thoáng và hạn chế bết dính mồ hôi. Định lượng 290gsm: Chất vải dày dặn giúp quần giữ được vẻ "vuông vức", không biến dạng sau thời gian dài. Công nghệ EasyCare: Vải có độ ổn định cao, tự hồi phục phẳng phiu sau khi giặt, tiết kiệm tối đa thời gian là ủi. 3. Chi tiết kỹ thuật: Bền bỉ và Tiện dụng Gia cố sườn: Hai đường may song song dọc sườn tạo lớp "khóa" bảo vệ, ngăn chặn tuyệt đối tình trạng bục chỉ khi vận động mạnh. Chỉ may chịu lực: Sử dụng chỉ Cotton siêu bền phối hợp mật độ cao giúp đường may phẳng phiu, không co rút. Túi ẩn bảo mật: Tích hợp thêm túi phụ có khóa kéo bên trong túi chính, giúp bảo vệ chìa khóa, thẻ ngân hàng an toàn khi di chuyển. TỔNG KẾT The No Style 242 là giải pháp hoàn hảo cho người năng động: Form dáng rộng rãi "hack" chiều cao, chất vải đanh chắc ít nhăn và độ bền công nghiệp vượt trội cho mọi hoạt động hàng ngày. THÔNG TIN NHANH Chất liệu: DurableTex™ Polyester Ultra Jacquard 290gsm, 100% Polyester Chi tiết sản phẩm: F4 - Loose Fit (Dáng Rộng), túi ẩn khóa kéo, ly xếp 3D. Lưu ý giặt ủi Giặt máy nhẹ nhàng, ủi ở nhiệt độ thấp (110°C – 120°C) để bảo vệ bề mặt vải.', 74550.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheNoStyle242a_38da9e97-0678-443a-a4e9-b563cd575249.jpg?v=1774608052', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheNoStyle242Nau1.jpg?v=1774323606', 'Cotton', 'Quần Kaki Ống Rộng DurableTex™ Vải Dày Dặn, Xếp Ly Che Khuyết Điểm The No Style 242 Màu Nâu Dáng Rộng Rãi F4', 422450.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 2);
