INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (61, 'YaMe.vn', 181600.0, '2026-05-21 11:40:31', 'Dây Nịt Dù #Y2010 221 Chất liệu: Dây: 65.5% Polypropylene, 24.1% Cao su, 10.4% Polyester. Khóa: Metal. Ưu điểm: Khóa Auto-Lock vô cấp: tùy chỉnh kích cỡ chính xác từng milimet. Sợi dệt co giãn đa điểm: mang lại cảm giác cực kỳ thoải mái. Chất liệu kháng nước: siêu bền và không bị gãy gập. Trọng lượng siêu nhẹ: êm ái khi vận động suốt ngày dài. Thiết kế Tactical hiện đại: không cần đục lỗ gây hỏng dây. Kích thước: Dây: Dài 120cm × Rộng 3.7cm × Dày 0.3cm. Khóa: Dài 3.9cm × Rộng 6.7cm. Kiểu khóa: Khóa gài tự động (Auto-Lock) không nấc lỗ. Lưu ý bảo quản: Treo thẳng dây sau khi sử dụng, hoặc bảo quản trong hộp. Tránh cuộn tròn quá chặt gây ảnh hưởng đến độ đàn hồi của sợi cao su. Không dùng máy sấy nhiệt hay bàn là tiếp xúc bề mặt. Chỉ dùng khăn mềm để vệ sinh mặt khóa, tránh hóa chất tẩy rửa mạnh. Xuất xứ: Trung Quốc TỔNG KẾT #Y2010 221 là giải pháp hoàn hảo thay thế dây nịt lỗ truyền thống, kết hợp giữa khóa vô cấp hiện đại và sợi dệt co giãn giúp vòng bụng luôn thoải mái trong mọi vận động hằng ngày.', 45400.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010221a.jpg?v=1773972173', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/DayN_tDu_Y2010221.png?v=1778819503', 'Mixed', 'Dây Nịt Vải Dù Chắc Chắn, Khóa Bấm Tự Động Tháo Mở Nhanh #Y2010 221 Màu Đen', 181600.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 1);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (62, 'YaMe.vn', 205600.0, '2026-05-21 11:40:31', 'Dây Nịt Dù #Y2010 177 Chất liệu: Dây: 65.5% Polypropylene, 24.1% Cao su, 10.4% Polyester. Ưu điểm: Khóa từ tính hiện đại: Đóng mở nhanh chóng chỉ trong một giây bằng lực hút nam châm. Co giãn thông minh: Thành phần cao su giúp dây tự điều chỉnh theo vòng bụng khi ngồi. Độ bền vượt trội: Cấu trúc sợi dệt cao cấp, kháng lực kéo và khó bị mất phom. Kháng nước nhẹ: Sợi tổng hợp chống thấm mồ hôi và vệ sinh cực kỳ dễ dàng. Kích thước: Dây: Dài 120cm × Rộng 3.7cm × Dày 0.25cm. Khóa: Dài 6.5cm × Rộng 4.0cm. Kiểu khóa: Khóa từ tính (Nam châm). Lưu ý bảo quản: Treo thẳng dây sau khi sử dụng hoặc bảo quản trong hộp chuyên dụng. Tránh cuộn tròn dây quá chặt gây ảnh hưởng đến cấu trúc sợi cao su. Tránh tiếp xúc với nước và độ ẩm cao; tuyệt đối không sử dụng máy sấy nhiệt. Chỉ dùng khăn mềm để vệ sinh mặt khóa, tránh các hóa chất tẩy rửa mạnh. Xuất xứ: Trung Quốc TỔNG KẾT Sự kết hợp hoàn hảo giữa khóa từ tính tiện lợi và sợi dệt đàn hồi bền bỉ, mang lại trải nghiệm êm ái và linh hoạt tối đa cho mọi hoạt động hằng ngày.', 51400.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010177a.jpg?v=1773973262', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010177XanhLa1.jpg?v=1773736272', 'Mixed', 'Dây Nịt Vải Dù Chắc Chắn, Khóa Hít Nam Châm Tiện Lợi #Y2010 177 Màu Xanh Lá', 205600.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 3);
