INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (66, 'YaMe.vn', 77600.0, '2026-05-21 11:40:31', 'Dây Nịt Đan #Y2010 174 Chất liệu: Dây: 70% Polyester, 30% Cao su đàn hồi. Khóa: Metal. Ưu điểm: Cấu trúc bện không lỗ: Cài khóa linh hoạt tại mọi vị trí trên dây. Vừa vặn từng milimet: Tinh chỉnh độ rộng tuyệt đối theo vòng eo thực tế. Co giãn đàn hồi cao: Thoải mái vận động nhờ lõi cao su 30% bền bỉ. Chống gỉ sét vượt trội: Đầu khóa Metal cao cấp, chịu được khí hậu nóng ẩm. Kích thước: Kích thước dây: Dài 120cm × Rộng 3.1cm × Dày 0.4cm. Kích thước khóa: Rộng 4.2cm × Dài 4.5cm. Kiểu khóa: Khóa kim. Lưu ý bảo quản: Treo thẳng dây sau khi sử dụng hoặc bảo quản trong hộp; tránh cuộn tròn quá chặt. Tránh tiếp xúc với nước và độ ẩm cao; tuyệt đối không dùng máy sấy nhiệt hay bàn ủi. Chỉ dùng khăn mềm để vệ sinh mặt khóa; tránh hóa chất tẩy rửa mạnh. TỔNG KẾT #Y2010 174 là giải pháp phụ kiện thông minh cho người năng động, kết hợp hoàn hảo giữa khả năng tùy chỉnh linh hoạt, độ đàn hồi vượt trội và sự chỉn chu trong mọi tình huống sử dụng.', 19400.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010174a.jpg?v=1773972713', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010174.png?v=1778818342', 'Mixed', 'Dây Nịt Vải Đan Co Giãn Bụng Thoải Mái, Khóa Cài Không Cần Bấm Lỗ #Y2010 174 Màu Đen', 77600.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 3);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (67, 'YaMe.vn', 77000.0, '2026-05-21 11:40:31', 'Túi Tote #Y2010 239 Chất liệu: Vải CanVas, 65% Cotton 35% Polyester Ưu điểm: Vải Canvas bền bỉ Sức chứa "không đáy": Thiết kế mở không vách ngăn dễ dàng đựng vừa những đồ vật size lớn, bảng vẽ khổ lớn, shopping, camping. Quai đeo liền khối: Thiết kế bản to liền thân túi giúp phân bổ trọng lượng đều lên vai, mang lại cảm giác êm ái. Điểm nhấn sang trọng: Trang bị logo kim loại chống gỉ sáng bóng, tạo nét tinh tế cho dòng túi tối giản. Kích thước: 35 x 40 x 3cm Phù hợp cho: Các "tín đồ" mua sắm cần một chiếc túi sức chứa lớn, người đi dã ngoại, sinh viên kiến trúc cần không gian cho bản vẽ lớn, Freelancer. Lưu ý bảo quản: Giặt tay nhẹ nhàng, tránh dùng chất tẩy mạnh; phơi trong bóng râm để giữ màu vải tốt nhất. TỔNG KẾT #Y2010 239 là sự kết hợp hoàn hảo giữa kích thước khủng và chất liệu dày dặn, giúp bạn mang theo "cả thế giới" trên vai một cách nhẹ nhàng và bền bỉ nhất.', 20000.0, 'Regular', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010239a.jpg?v=1770625469', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010239.png?v=1778818715', 'Cotton', 'Túi Tote Canvas Big Size Sức Chứa Khủng #Y2010 239', 77000.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 3);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (68, 'YaMe.vn', 757150.0, '2026-05-21 11:40:31', 'Áo Khoác Kaki DurableTex™ The Worker 011 Chất liệu DurableTex™ 290gsm: Đanh chắc và Thoáng da Vật liệu 100% Cotton: Loại bỏ hoàn toàn sợi tổng hợp nilon, giúp nhiệt lượng cơ thể lưu thông tự nhiên, không gây cảm giác bết dính hay hầm bí khi mặc cả ngày dài. Kỹ thuật dệt Twill (Vân chéo): Tạo bề mặt đanh chắc, chịu được ma sát cao và hạn chế tối đa việc bị xé rách trong quá trình vận động mạnh. Cấu trúc rập Regular Fit & Kỹ thuật rã Decoup: Giải phóng cử động Kỹ thuật rã Decoup: Thay vì chiết eo thông thường, thân trước được chia khối 3D giúp áo ôm nhẹ theo đường nét cơ thể một cách tự nhiên và nam tính. Tối ưu không gian: Hạ sâu vòng nách giúp triệt tiêu tình trạng kích nách khi vươn tay. Trọng lượng vải được tính toán dồn đều lên vai, không gây ghì cổ, giữ phom áo luôn phẳng phiu. Tiêu chuẩn may Heavy-Duty: Gia cố bền bỉ Chỉ may sợi lớn: Sử dụng chỉ Cotton cơ số lớn, chịu lực kéo cực tốt, chống đứt gãy đường diễu nổi. Chốt bọ Bartack: Gia cố chắc chắn tại miệng túi và trụ tay, triệt tiêu hoàn toàn nguy cơ bung tét hay xé rách vải. Ép keo Fusing: Lá cổ và nắp túi được ép lụa bên trong, giúp bề mặt luôn phẳng phiu, chống quăn mép sau nhiều lần giặt. Hệ thống túi chịu lực & Tính ổn định phom dáng Túi chống giãn: Miệng túi sườn được xử lý nẹp gia cố ẩn bên trong như một bộ khung, giúp túi luôn nằm phẳng, không bị chảy xệ hay mất phom khi đựng vật dụng nặng (điện thoại, ví tiền). Vải không co giãn: Tận dụng đặc tính tự nhiên của Cotton định lượng cao để giữ cấu trúc khối hộp (Boxy) ổn định, không bị chảy xệ hay biến dạng sau thời gian dài sử dụng. TỔNG KẾT The Worker 011 là giải pháp kỹ thuật cho dòng áo khoác vải dày nhưng vẫn đảm bảo sự linh hoạt tuyệt đối. Với sự kết hợp giữa vải Kaki 290gsm bền bỉ và cấu trúc rập F3 giải phóng cử động, đây là sản phẩm dành cho những người cần sự bền bỉ thực dụng và diện mạo chỉn chu. THÔNG TIN NHANH Chất liệu: DurableTex™ Cotton Ultra Twill 290gsm, 100% Cotton Chi tiết sản phẩm: F3 - Regular Fit (Dáng Tiêu Chuẩn), Hệ thống 4 túi, Bộ nút kim loại. Lưu ý giặt/ ủi: Lộn trái sản phẩm khi giặt, tránh ma sát mạnh cục bộ (đặc biệt với màu đậm) để không bị gợn màu trắng. Giặt máy với nước lạnh (&lt;40°C), có thể sấy ở nhiệt độ trung bình. Ủi ở nhiệt độ cao để áo vào phom đứng dáng nhất.', 39850.0, 'Boxy Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheWorker011a.jpg?v=1769590004', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheWorker011XamNhat1.jpg?v=1769590004', 'Cotton', 'Áo Khoác Kaki DurableTex™ Vải Cotton Dày Dặn Chắn Gió Cản Bụi The Worker 011 Màu Xám Nhạt Dáng Vừa Vặn F3', 757150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 1);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (69, 'YaMe.vn', 237600.0, '2026-05-21 11:40:31', 'Túi Cross #Y2010 225 Chống thấm nước và chịu va chạm tốt Túi sử dụng loại vải có mật độ sợi dày (900D), vượt trội hơn so với các dòng túi phổ thông mỏng nhẹ. Độ dày này giúp túi khó bị sờn rách khi vô tình cọ xát vào tường hay vật cứng. Đặc biệt, bề mặt vải được cán một lớp màng nhựa dẻo dày khoảng 1mm. Lớp màng này hoạt động như một tấm chắn, giúp nước mưa hay chất lỏng trượt đi ngay lập tức thay vì thấm vào trong, giữ an toàn cho đồ dùng của bạn. Giữ phom dáng, dễ lau chùi Nhờ kết cấu vải đanh chắc, túi luôn giữ được hình dáng đứng, không bị nhăn nhúm hay bẹp xuống ngay cả khi bạn để ít đồ. Bề mặt túi có độ mịn và "lỳ", không thô ráp, giúp hạn chế bám bụi bẩn. Khi túi dính bẩn, bạn chỉ cần dùng khăn ẩm lau nhẹ là sạch, không cần giặt giũ cầu kỳ. Mềm mại, đeo êm người Dù vải dày nhưng không hề cứng nhắc nhờ lớp phủ bề mặt có pha trộn thành phần cao su. Túi vẫn giữ được độ dẻo dai, các đường cong mềm mại ôm sát cơ thể khi đeo. Bạn sẽ không gặp cảm giác cộm cứng hay khó chịu trong quá trình di chuyển, vận động hàng ngày. TỔNG KẾT Bộ sưu tập #Y2010 tập trung vào giá trị sử dụng thực tế: kiên cố trước va chạm và thời tiết nhưng vẫn đảm bảo sự êm ái, gọn gàng. Đây là lựa chọn tin cậy cho những ai cần một chiếc túi chống chịu tốt nhưng vẫn giữ được vẻ ngoài chỉn chu. THÔNG TIN NHANH Kích thước: 35x28x17cm Chất liệu: Vải chính 900HD PUL, lót 210D thành phần 100% Polyester Đặc điểm sản phẩm: Bề mặt mịn lỳ, kháng nước Lưu ý giặt ủi: Chỉ nên lau sạch bằng khăn ẩm. Tuyệt đối tránh phơi nắng gắt hoặc sấy nóng để không làm hỏng lớp màng chống thấm. Lưu ý kháng nước: Vải trượt nước tốt, nhưng hạn chế đi mưa lớn lâu để tránh thấm qua khe dây kéo, đường chỉ.', 59400.0, 'Slim Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010225.jpg?v=1774954303', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/Y2010225_a4bcf23f-a6f4-4257-a40e-9bbbd1f4be32.jpg?v=1777089896', 'Mixed', 'Túi Đeo Chéo Cross Bag Trượt Nước #Y2010 225 (35x28x17)', 237600.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 3);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (70, 'YaMe.vn', 263150.0, '2026-05-21 11:40:31', 'Áo Thun Cổ Tròn Tay Ngắn AirDry™ The No Style 209 Kỹ Thuật In Dẻo Rubber & May đắp vải Appliqué: Slogan "Peace in every corner" in Rubber (in dẻo) đàn hồi cao, thẩm thấu sâu vào sợi vải giúp chống nứt vỡ, bong tróc khi giặt máy. Con số "36" ứng dụng kỹ thuật thêu đắp Appliqué với vải nền cắt laser, tạo khối 3D sắc nét, bền bỉ và giữ chuẩn phom sau thời gian dài sử dụng. Vải lưới AirDry™ 240gsm dày dặn thoáng mát: Cấu trúc lưới mở (Open-Air) tạo cơ chế làm mát tự nhiên, cho phép gió lưu thông trực tiếp qua bề mặt vải. Định lượng 240gsm giúp áo dày dặn, đứng phom và không dính sát vào da khi đổ mồ hôi. Phom Boxy Giấu Dáng Hiệu Quả: Phom dáng hộp vuông với thân áo nới rộng 4cm và vai trễ 7cm. Cấu trúc này không chỉ giúp giấu dáng hiệu quả mà còn triệt tiêu tình trạng cấn nách, mang lại sự thoải mái hoàn toàn khi lái xe hay vận động. Độ bền công nghiệp: Mật độ chỉ may dày kết hợp cùng kỹ thuật cân bằng cổ áo (chia 4 điểm) giúp sản phẩm giữ đúng phom dáng tròn trịa, không bị vặn lệch hay biến dạng sau nhiều lần giặt. Toàn bộ đường may được bọc kín bằng kỹ thuật vắt sổ bản rộng và chỉ cotton siêu mềm. Hai đường viền chạy dọc vai giúp giữ phom tay áo luôn phẳng phiu, không bị nhăn nhúm khi vận động. TỔNG KẾT Sản phẩm là lời giải cho bài toán hầm bí khi vận động, mang đến trải nghiệm mặc nhẹ nhàng nhưng vẫn giữ được diện mạo chỉn chu, mạnh mẽ. THÔNG TIN NHANH Chất liệu: AirDry™ Polyester Ultra Mesh 240gsm, 100% Polyester Chi tiết sản phẩm: F4 - Loose Fit (Dáng Rộng), In dẻo Rubber, Lưu ý giặt ủi: Nên sử dụng túi giặt để bảo vệ cấu trúc lưới. Giặt nước lạnh (&lt;40°C), không dùng thuốc tẩy. Phơi trong bóng râm, tránh nắng gắt trực tiếp. Lộn trái áo khi ủi (nhiệt độ tối đa 110°C). Tips mặc đẹp: Mix & match thêm một lớp áo mỏng bên trong. Sự kết hợp này giúp xử lý khéo léo độ xuyên thấu đặc trưng của mắt lưới, sẽ mang lại diện mạo chỉn chu và có gu hơn cho bạn.', 13850.0, 'Boxy Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheNoStyle207-208-209a.jpg?v=1769509419', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheNoStyle209_f4de68a6-7181-493c-8bcd-d2cbbe1f9331.jpg?v=1778485648', 'Cotton', 'Áo Thun Vải Dệt Lưới AirDry™ Thoát Nhiệt Nhanh "PEACE IN EVERY CORNER" The No Style 209 Màu Xanh Lá Đậm Dáng Rộng Rãi F4', 263150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 1);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (71, 'YaMe.vn', 263150.0, '2026-05-21 11:40:31', 'Áo Thun Cổ Tròn Tay Ngắn AirDry™ The No Style 208 Kỹ thuật In Rubber & Cấu trúc thân gia cố Hình in bền bỉ: Sử dụng mực dẻo Rubber cho hình in. Mực có độ đàn hồi cao, bám sâu vào vải giúp hình in co giãn theo chuyển động mà không lo nứt vỡ. Ráp phối khỏe khoắn: Thân trước được ghép mảnh và may diễu đè phẳng, tạo bề mặt ổn định cho hình in và mang lại cảm giác mịn mướt, không cộm da. Hệ thống sọc Sporty: 4 đường sọc dọc tay được may chắc chắn, đóng vai trò như "bộ khung" giữ tay áo luôn thẳng, chống vặn xoắn sau khi giặt. Chất liệu AirDry™ Mesh 240gsm chuyên dụng Thoáng mát tuyệt đối: Cấu trúc lưới mở (Open-Air) cho phép không khí lưu thông xuyên suốt, giải tỏa nhiệt lượng cơ thể tức thì. Đứng phom vượt trội: Định lượng vải dày 240gsm (nặng gấp đôi vải lưới thông thường) giúp áo có độ rũ đẹp, tạo phom dáng cứng cáp và không bết dính vào da khi đổ mồ hôi. Thiết kế Boxy & Vai trễ tối ưu vận động Tự do chuyển động: Phom dáng khối hộp (Boxy) rộng rãi kết hợp hạ vai trễ (+7cm) giúp triệt tiêu áp lực lên cầu vai và nách, mang lại sự thoải mái tối đa khi vận động mạnh. Gia cố đường may và tăng độ êm ái cho da Đường may chắc chắn: Mật độ chỉ dày khóa chặt mắt lưới, chống tuột chỉ. Êm ái cho da: Cổ áo được xử lý chia điểm đối xứng giúp giữ phom tròn đều. Đường may gáy bọc dải vải mềm loại bỏ hoàn toàn cảm giác châm chích vùng cổ. TỔNG KẾT The No Style 208 là sự kết hợp hoàn hảo giữa hiệu suất làm mát của chất liệu lưới AirDry™ và độ bền bỉ từ kỹ thuật gia cố đường may chuyên sâu. Đây là lựa chọn lý tưởng cho những ai yêu thích phong cách năng động, cần một chiếc áo thoáng mát tuyệt đối nhưng vẫn giữ được phom dáng cứng cáp, chỉn chu hằng ngày. THÔNG TIN NHANH Chất liệu: AirDry™ Polyester Ultra Mesh 240gsm, 100% Polyester Chi tiết sản phẩm: F4 - Loose Fit (Dáng Rộng), phối mảng thân trước, in dẻo Rubber, sọc viền tay. Lưu ý giặt/ ủi: Sử dụng túi giặt để bảo vệ bề mặt lưới. Giặt nước lạnh (&lt;40°C), không dùng thuốc tẩy. Phơi trong bóng râm, tránh nắng gắt để bảo vệ màu sắc và hình in. Ủi ở nhiệt độ thấp (tối đa 110°C). Tips mặc đẹp: Mix & match thêm một lớp áo mỏng bên trong. Sự kết hợp này giúp xử lý khéo léo độ xuyên thấu đặc trưng của mắt lưới, sẽ mang lại diện mạo chỉn chu và có gu hơn cho bạn.', 13850.0, 'Boxy Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheNoStyle207-208-209a.jpg?v=1769509419', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/AoThunC_TronAirDry_TheNoStyle208.jpg?v=1778227987', 'Mixed', 'Áo Thun Dệt Lưới AirDry™ Thoát Nhiệt Nhanh "GOLDEN BRIDGE''S EMBRACE" The No Style 208 Màu Đỏ Dáng Rộng Rãi F4', 263150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 1);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (72, 'YaMe.vn', 263150.0, '2026-05-21 11:40:31', 'Áo Thun Cổ Tròn Tay Ngắn AirDry™ The No Style 207 Công Nghệ In Dẻo Rubber Bền Bỉ Họa tiết "NEVER SLEEPS" và con số "68" được xử lý bằng kỹ thuật in Rubber (in dẻo) cao cấp. Mực in có độ đàn hồi cực tốt, giúp hình in co giãn theo sợi vải mà không bị nứt vỡ hay bong tróc, giữ trọn tính thẩm mỹ sau nhiều lần giặt. Vải Lưới AirDry™ 240gsm Dày Dặn Nhưng Thoáng Mát 360 Độ Phá bỏ định kiến về vải lưới mỏng manh, chất liệu AirDry™ định lượng 240gsm giúp áo đứng phom vuông vức chuẩn Streetwear. Hàng nghìn mắt lưới đóng vai trò như "cửa sổ khí" giúp nhiệt lượng thoát ra tức thì, mang lại cảm giác mát lạnh như có máy điều hòa tự nhiên bao quanh cơ thể. Phom Dáng Loose Fit Tối Ưu Không Gian "Thở" Thiết kế rập hình hộp (Boxy Shape) với vai trễ và hạ nách sâu giúp triệt tiêu cảm giác gò bó. Khoảng không gian đệm giữa áo và cơ thể cho phép gió lưu thông liên tục, giúp da luôn khô thoáng ngay cả khi bạn di chuyển liên tục ngoài phố. Tiêu Chuẩn May Êm Ái Vượt Trội Loại bỏ hoàn toàn cảm giác châm chích thường gặp của vải lưới. Toàn bộ đường may được bọc kín bằng kỹ thuật vắt sổ bản rộng và chỉ cotton siêu mềm. Mật độ chỉ dày dặn giúp khóa chặt kết cấu vải, đảm bảo áo không bị bung xì hay mất phom khi giặt máy. TỔNG KẾT No Style 207 là bản tuyên ngôn mới cho Streetwear khi thay thế Cotton truyền thống bằng cấu trúc lưới AirDry™ 240gsm táo bạo. Đây là lựa chọn số 1 cho những ai tìm kiếm sự gai góc trong chất liệu nhưng vẫn ưu tiên độ bền và khả năng thoát nhiệt vượt trội. THÔNG TIN NHANH Chất liệu: AirDry™ Polyester Ultra Mesh (240gsm) – Co giãn, khô nhanh, thoát nhiệt tốt. Chi tiết sản phẩm: Phom F4 Loose Fit (Vai trễ), hình in Rubber dẻo, đường may bọc viền chống ngứa. Lưu ý giặt ủi: Sử dụng túi giặt để bảo vệ mắt lưới (bắt buộc). Giặt nước lạnh hoặc ấm nhẹ (&lt; 40°C), không dùng thuốc tẩy. Phơi trong bóng râm, ủi ở nhiệt độ thấp (tối đa 110°C). Tips mặc đẹp: Mix & match thêm một lớp áo mỏng bên trong. Sự kết hợp này giúp xử lý khéo léo độ xuyên thấu đặc trưng của mắt lưới, sẽ mang lại diện mạo chỉn chu và có gu hơn cho bạn.', 13850.0, 'Boxy Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheNoStyle207-208-209a.jpg?v=1769509419', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/TheNoStyle207XanhDuongDam1.jpg?v=1769497934', 'Cotton', 'Áo Thun Vải Dệt Lưới AirDry™ Thoát Nhiệt Nhanh "NEVER SLEEPS" The No Style 207 Màu Xanh Dương Đậm Dáng Rộng Rãi F4', 263150.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 1);
