INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (74, 'YaMe.vn', 209950.0, '2026-05-21 11:40:31', 'Áo Thun Tay Dài FlexFit™ Non Branded 052 Phom Dáng Regular Fit Và Tay Raglan Giải Phóng Đôi Vai Thiết kế Raglan: Loại bỏ đường may vai truyền thống, triệt tiêu tình trạng nhăn nách và tự điều chỉnh theo độ xuôi vai của mỗi người. Nới rộng cử động: Phần ngực được cộng thêm 2cm giúp không khí lưu thông, đảm bảo xoay trở cánh tay thoải mái mà không gây kéo căng mặt vải. Ổn định phom dáng: Lai áo được tăng chiều dài tạo độ đầm, giúp áo không bị giựt ngược khi vận động mạnh. 2.Chất liệu FlexFit™ 190gsm chuyên dụng Mỏng nhẹ & Thoáng khí: Định lượng 190gsm mang lại cảm giác nhẹ tênh, cực kỳ phù hợp để làm lớp lót (layering) bên trong áo khoác mà không gây cộm hay hầm bí. Sợi nén Compact Yarn: Bề mặt vải được xử lý giấu đầu xơ, hạn chế tối đa tình trạng xù lông và giữ áo luôn mới sau nhiều lần giặt. Co giãn 4 chiều: Thành phần 8% Spandex đảm bảo áo co giãn linh hoạt và tự hồi phục phom dáng ban đầu, chống tình trạng dão cổ và thân áo. 3.Chi tiết công năng & Hoàn thiện kỹ thuật Thiết kế đa năng: Tay áo kéo dài tích hợp lỗ xỏ ngón giúp cố định ống tay khi mặc lớp ngoài và giữ ấm bàn tay. Giải phóng cử động: Chi tiết xẻ lai hông giúp ngồi thoải mái, kết hợp kỹ thuật đóng bọ (Bartack) tại các điểm nối để chống xé rách khi chịu lực căng. Đường may 4 chỉ: Mật độ chỉ dày giúp tăng tuổi thọ sản phẩm và co giãn linh hoạt. TỔNG KẾT Áo thun Non Branded 052 là sự kết hợp giữa phom Regular Fit linh hoạt và chất liệu FlexFit™ mỏng nhẹ. Đây là lựa chọn kỹ thuật tối ưu cho những ai cần một chiếc áo lót bên trong tinh tế hoặc áo mặc độc bản có khả năng thoát nhiệt nhanh và hỗ trợ vận động tối đa. THÔNG TIN NHANH Chất liệu: FlexFit™ Cotton Ultra Single 190gsm, 92% Cotton 8% Spandex Chi tiết sản phẩm: F3 - Regular Fit (Dáng Tiêu Chuẩn), tay Raglan có xỏ ngón, xẻ lai hông. Lưu ý giặt/ ủi: Lộn trái sản phẩm khi giặt máy để bảo vệ bề mặt sợi nén; Ưu tiên sử dụng túi giặt và chế độ giặt nhẹ; Tránh sấy ở nhiệt độ cao để giữ độ bền sợi Spandex. Xuất xứ: Việt Nam', 37050.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/NonBranded052a_ccfb3402-fcf5-43d4-97e6-296ad177c077.jpg?v=1779259478', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/NonBranded052XamNhat1.jpg?v=1769496830', 'Cotton', 'Áo Thun Tay Dài Raglan FlexFit™ Vải Mỏng Mịn Có Lỗ Xỏ Ngón Tiện Lợi Non Branded 052 Màu Xám Nhạt Dáng Vừa Vặn F3', 209950.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 1);
INSERT INTO product (product_id, brand, cost_price, created_at, description, discount_amount, form, image_url_back, image_url_front, material, product_name, price, quantity, rating, status, unit, updated_at, category) VALUES (75, 'YaMe.vn', 209950.0, '2026-05-21 11:40:31', 'Áo Thun Tay Dài FlexFit™ Non Branded 052 Phom Dáng Regular Fit Và Tay Raglan Giải Phóng Đôi Vai Thiết kế Raglan: Loại bỏ đường may vai truyền thống, triệt tiêu tình trạng nhăn nách và tự điều chỉnh theo độ xuôi vai của mỗi người. Nới rộng cử động: Phần ngực được cộng thêm 2cm giúp không khí lưu thông, đảm bảo xoay trở cánh tay thoải mái mà không gây kéo căng mặt vải. Ổn định phom dáng: Lai áo được tăng chiều dài tạo độ đầm, giúp áo không bị giựt ngược khi vận động mạnh. 2.Chất liệu FlexFit™ 190gsm chuyên dụng Mỏng nhẹ & Thoáng khí: Định lượng 190gsm mang lại cảm giác nhẹ tênh, cực kỳ phù hợp để làm lớp lót (layering) bên trong áo khoác mà không gây cộm hay hầm bí. Sợi nén Compact Yarn: Bề mặt vải được xử lý giấu đầu xơ, hạn chế tối đa tình trạng xù lông và giữ áo luôn mới sau nhiều lần giặt. Co giãn 4 chiều: Thành phần 8% Spandex đảm bảo áo co giãn linh hoạt và tự hồi phục phom dáng ban đầu, chống tình trạng dão cổ và thân áo. 3.Chi tiết công năng & Hoàn thiện kỹ thuật Thiết kế đa năng: Tay áo kéo dài tích hợp lỗ xỏ ngón giúp cố định ống tay khi mặc lớp ngoài và giữ ấm bàn tay. Giải phóng cử động: Chi tiết xẻ lai hông giúp ngồi thoải mái, kết hợp kỹ thuật đóng bọ (Bartack) tại các điểm nối để chống xé rách khi chịu lực căng. Đường may 4 chỉ: Mật độ chỉ dày giúp tăng tuổi thọ sản phẩm và co giãn linh hoạt. TỔNG KẾT Áo thun Non Branded 052 là sự kết hợp giữa phom Regular Fit linh hoạt và chất liệu FlexFit™ mỏng nhẹ. Đây là lựa chọn kỹ thuật tối ưu cho những ai cần một chiếc áo lót bên trong tinh tế hoặc áo mặc độc bản có khả năng thoát nhiệt nhanh và hỗ trợ vận động tối đa. THÔNG TIN NHANH Chất liệu: FlexFit™ Cotton Ultra Single 190gsm, 92% Cotton 8% Spandex Chi tiết sản phẩm: F3 - Regular Fit (Dáng Tiêu Chuẩn), tay Raglan có xỏ ngón, xẻ lai hông. Lưu ý giặt/ ủi: Lộn trái sản phẩm khi giặt máy để bảo vệ bề mặt sợi nén; Ưu tiên sử dụng túi giặt và chế độ giặt nhẹ; Tránh sấy ở nhiệt độ cao để giữ độ bền sợi Spandex. Xuất xứ: Việt Nam', 37050.0, 'Loose Fit', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/NonBranded052a_ccfb3402-fcf5-43d4-97e6-296ad177c077.jpg?v=1779259478', 'https://cdn.shopify.com/s/files/1/0932/5569/6681/files/NonBranded052XamDuong1.jpg?v=1769496582', 'Cotton', 'Áo Thun Tay Dài Raglan FlexFit™ Vải Mỏng Mịn Có Lỗ Xỏ Ngón Tiện Lợi Non Branded 052 Màu Xanh Dương Dáng Vừa Vặn F3', 209950.0, 100, 4.5, 'ACTIVE', 'Cai', '2026-05-21 11:40:31', 1);
